mapper.select:
/*"getCatalogItemRecommand"*/ SELECT B.* FROM ( SELECT DECODE (IMG_NAME, NULL, '/resources/images/icon_emptyimg.gif', '/' || IMG_DIR || '/' || IMG_NAME) IMG_NAME, A.ITEM_NO ITEM_NO, A.DESCRIPTION DESCRIPTION, A.SPECIFICATION SPECIFICATION, A.USER_PRICE USER_PRICE FROM PRMTITEM A WHERE A.ITEM_FLAG IN ('N', 'G') AND A.ITEM_STATUS = 'N' AND A.STATUS = 'V'
AND A.CATEGORY_NO IN (SELECT STD_CATEG_ID FROM ICOMBYCA WHERE COM_CODE='PRMTITEM' AND PID= #{st_pid} )
AND A.CATEGORY_NO = #{st_std_categ_id}
ORDER BY DBMS_RANDOM.RANDOM ) B WHERE ROWNUM <= 4
